tasks.solution:
using System;
using System.Collections.Generic;

class Program
{
    static int MaxOfThree(int a, int b, int c)
    {
        int biggest = a;
        if (b > biggest)
        {
            biggest = b;
        }
        if (c > biggest)
        {
            biggest = c;
        }
        return biggest;
    }
}

