using System;
using System.Collections.Generic;

class Program
{
    static string Grade(int score)
    {
        if (score >= 85)
        {
            return "отлично";
        }
        else if (score >= 70)
        {
            return "хорошо";
        }
        else if (score >= 50)
        {
            return "удовлетворительно";
        }
        else
        {
            return "плохо";
        }
    }
}
